parameters.functionCode:
// Validate match completion request
const { matchId, results, finalStats } = $input.first().json;

if (!matchId || !results) {
  throw new Error('Match ID and results are required');
}

// Validate results structure
if (!results.playerResults || !Array.isArray(results.playerResults)) {
  throw new Error('Invalid results structure');
}

// Calculate additional statistics
const completionTime = new Date().toISOString();
const totalKills = results.playerResults.reduce((sum, player) => sum + player.statistics.kills, 0);
const totalDamage = results.playerResults.reduce((sum, player) => sum + player.statistics.damageDealt, 0);
const avgMatchDuration = results.duration / 1000; // Convert to seconds

return {
  matchId,
  results,
  finalStats,
  completionTime,
  calculatedStats: {
    totalKills,
    totalDamage,
    avgMatchDuration,
    playerCount: results.playerResults.length
  },
  processed: false
};

// Update player rankings for each participant
const matchData = $input.first().json;
const completionData = $input.item.json;
const rankingUpdates = [];

completionData.results.playerResults.forEach(playerResult => {
  const player = matchData.players.find(p => p.id === playerResult.playerId);
  if (player) {
    rankingUpdates.push({
      playerId: playerResult.playerId,
      playerName: player.name,
      characterClass: player.character.class,
      matchResult: {
        placement: playerResult.placement,
        kills: playerResult.statistics.kills,
        deaths: playerResult.statistics.deaths,
        assists: playerResult.statistics.assists,
        kda: playerResult.statistics.kda,
        damageDealt: playerResult.statistics.damageDealt,
        healingDone: playerResult.statistics.healingDone,
        mvp: playerResult.mvp || false,
        score: playerResult.statistics.score,
        arenaType: matchData.arenaType,
        opponentAverageElo: completionData.calculatedStats.opponentAverageElo || 1500
      }
    });
  }
});

return { rankingUpdates };

// Process achievements for each player
const playerResults = $input.first().json.results.playerResults;
const achievementUnlocks = [];

playerResults.forEach(playerResult => {
  // Check for various achievement conditions
  const achievements = [];

  // First blood achievement
  if (playerResult.statistics.kills === 1 && playerResult.placement === 1) {
    achievements.push({
      id: 'first_blood_victory',
      name: 'First Blood Victory',
      description: 'Win a match with exactly 1 kill',
      rarity: 'common'
    });
  }

  // Dominating performance
  if (playerResult.statistics.kills >= 10 && playerResult.statistics.deaths <= 2) {
    achievements.push({
      id: 'dominating',
      name: 'Dominating Performance',
      description: 'Get 10+ kills with 2 or fewer deaths',
      rarity: 'rare'
    });
  }

  // Untouchable
  if (playerResult.statistics.kills >= 5 && playerResult.statistics.deaths === 0) {
    achievements.push({
      id: 'untouchable',
      name: 'Untouchable',
      description: 'Get 5+ kills without dying',
      rarity: 'epic'
    });
  }

  // Damage dealer
  if (playerResult.statistics.damageDealt >= 5000) {
    achievements.push({
      id: 'damage_dealer',
      name: 'Damage Dealer',
      description: 'Deal 5000+ damage in a single match',
      rarity: 'uncommon'
    });
  }

  // Team player (high assists)
  if (playerResult.statistics.assists >= 10) {
    achievements.push({
      id: 'team_player',
      name: 'Team Player',
      description: 'Get 10+ assists in a single match',
      rarity: 'uncommon'
    });
  }

  if (achievements.length > 0) {
    achievementUnlocks.push({
      playerId: playerResult.playerId,
      playerName: playerResult.playerName,
      achievements: achievements
    });
  }
});

return { achievementUnlocks };

// Calculate and distribute rewards
const playerResults = $input.first().json.results.playerResults;
const rewardDistributions = [];

playerResults.forEach(playerResult => {
  let xpReward = 100; // Base XP
  let goldReward = 50; // Base gold

  // Placement multipliers
  const placementMultipliers = {
    1: 3.0,
    2: 2.0,
    3: 1.5,
    4: 1.2,
    5: 1.0
  };

  const multiplier = placementMultipliers[playerResult.placement] || 0.8;
  xpReward = Math.floor(xpReward * multiplier);
  goldReward = Math.floor(goldReward * multiplier);

  // Performance bonuses
  if (playerResult.statistics.kills >= 10) {
    xpReward += 200;
    goldReward += 100;
  }

  if (playerResult.mvp) {
    xpReward += 150;
    goldReward += 75;
  }

  if (playerResult.statistics.damageDealt >= 3000) {
    xpReward += 100;
    goldReward += 50;
  }

  rewardDistributions.push({
    playerId: playerResult.playerId,
    playerName: playerResult.playerName,
    rewards: {
      xp: xpReward,
      gold: goldReward,
      score: playerResult.statistics.score
    },
    placement: playerResult.placement,
    mvp: playerResult.mvp
  });
});

return { rewardDistributions };

// Generate match summary for analytics
const matchData = $node["Retrieve Match Data"].json;
const completionData = $input.first().json;
const summary = {
  matchId: completionData.matchId,
  arenaType: matchData.arenaType,
  completionTime: completionData.completionTime,
  duration: completionData.results.duration,
  playerCount: completionData.results.playerResults.length,
  totalKills: completionData.calculatedStats.totalKills,
  totalDamage: completionData.calculatedStats.totalDamage,
  winner: completionData.results.winner,
  winningPlacement: completionData.results.playerResults.find(p => p.playerId === completionData.results.winner)?.placement || 1,
  topScorer: completionData.results.playerResults.reduce((top, player) => 
    player.statistics.score > (top?.statistics.score || 0) ? player : top, null
  ),
  mvp: completionData.results.playerResults.find(p => p.mvp),
  gameModeStats: {
    avgKillsPerPlayer: completionData.calculatedStats.totalKills / completionData.results.playerResults.length,
    avgDamagePerPlayer: completionData.calculatedStats.totalDamage / completionData.results.playerResults.length,
    avgScore: completionData.results.playerResults.reduce((sum, p) => sum + p.statistics.score, 0) / completionData.results.playerResults.length
  }
};

return { summary };

